import React, { useEffect, useMemo, useRef, useState } from "react";
import { startLogin } from "@/const";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { Bar, BarChart, CartesianGrid, Legend, Line, LineChart, PolarAngleAxis, PolarGrid, PolarRadiusAxis, Radar, RadarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { CalendarDays, Check, ChevronRight, CircleHelp, Clock3, Download, FileText, Flag, LayoutDashboard, ListChecks, Menu, Pause, Play, Plus, RotateCcw, Search, Settings, ShieldCheck, Target, TimerReset, TrendingUp, Upload, Users, X } from "lucide-react";

type Task = { id: string; title: string; subject: string; due: string; minutes: number; done: boolean; kind: string };
type Plan = { id: string; date: string; subject: string; content: string; minutes: number; priority: string; done: boolean; status?: "planned" | "cancelled"; fixed?: boolean };
type Exam = { id: string; name: string; date: string; term: string; scores: Record<string, number>; max: number };
type ReviewRecord = { id: string; date: string; correct: boolean; understanding: number; seconds?: number; memo?: string };
type ReviewSchedule = { id: string; weaknessId: string; due: string; status: "pending" | "done"; completedAt?: string };
type Weakness = { id: string; subject: string; unit: string; cause: string; review: string; done: boolean; question?: string; answer?: string; explanation?: string; imageData?: string; difficulty?: string; createdAt?: string; memo?: string; history?: ReviewRecord[] };
type Study = { id: string; date: string; subject: string; minutes: number; note: string; planId?: string; method?: string; understanding?: number; difficultPoint?: string; nextAction?: string };
type Goal = { hours: number; score: number; reflection?: string; subjectTargets?: Record<string, number>; maxDailyMinutes?: number };
type PlanAdjustment = { id: string; createdAt: string; reason: string; before: Plan[]; after: Plan[]; undone?: boolean };
type SchoolEvent = { id: string; title: string; date: string; kind: string; subject: string; note: string };
type TimetableEntry = { id: string; day: number; period: number; subject: string; room: string; teacher: string };

type Store = { tasks: Task[]; plans: Plan[]; exams: Exam[]; weaknesses: Weakness[]; studies: Study[]; events: SchoolEvent[]; timetable: TimetableEntry[]; reviewSchedules: ReviewSchedule[]; planAdjustments: PlanAdjustment[]; goal: Goal };
const subjects = ["国語", "数学", "英語", "理科", "社会", "音楽", "美術", "保体", "技術家庭"];
const mainSubjects = subjects.slice(0, 5);
const initial: Store = { tasks: [], plans: [], exams: [], weaknesses: [], studies: [], events: [], timetable: [], reviewSchedules: [], planAdjustments: [], goal: { hours: 5, score: 400, subjectTargets: {}, maxDailyMinutes: 120 } };
const sampleData: Store = {
  tasks: [{ id: "sample-t1", title: "数学ワークを進める", subject: "数学", due: "2026-10-18", minutes: 30, done: false, kind: "自主学習" }],
  plans: [{ id: "sample-p1", date: "2026-10-18", subject: "英語", content: "教科書を音読する", minutes: 20, priority: "中", done: false }],
  exams: [{ id: "sample-e1", name: "サンプルテスト", date: "2026-10-10", term: "2学期", max: 100, scores: { 国語: 72, 数学: 80, 英語: 68, 理科: 75, 社会: 70 } }],
  weaknesses: [{ id: "sample-w1", subject: "英語", unit: "復習したい単元", cause: "あとでメモを追加", review: "2026-10-20", done: false }],
  studies: [{ id: "sample-s1", date: "2026-10-17", subject: "数学", minutes: 25, note: "サンプル記録" }],
  events: [],
  timetable: [],
  reviewSchedules: [],
  planAdjustments: [],
  goal: { hours: 5, score: 400 },
};

const uid = () => Math.random().toString(36).slice(2, 9);
const today = new Date().toISOString().slice(0, 10);
const formatDate = (iso: string) => new Intl.DateTimeFormat("ja-JP", { month: "long", day: "numeric", weekday: "short" }).format(new Date(`${iso}T00:00:00`));
const isLegacySeed = (value: Store) => ["t1", "t2", "t3", "p1", "p2", "p3", "e1", "e2", "w1", "w2", "s1", "s2", "s3"].some(id => [...value.tasks, ...value.plans, ...value.exams, ...value.weaknesses, ...value.studies].some((item: any) => item.id === id));
const isRecord = (value: unknown): value is Record<string, any> => Boolean(value && typeof value === "object" && !Array.isArray(value));
const validDate = (value: unknown) => typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value);
const cleanLoadedStore = (value: unknown): Store => {
  if (!isRecord(value) || !Array.isArray(value.tasks) || !Array.isArray(value.plans) || !Array.isArray(value.exams) || !Array.isArray(value.weaknesses) || !Array.isArray(value.studies) || !isRecord(value.goal)) return initial;
  const tasks = value.tasks; const plans = value.plans; const exams = value.exams; const weaknesses = value.weaknesses; const studies = value.studies; const events = Array.isArray(value.events) ? value.events : []; const timetable = Array.isArray(value.timetable) ? value.timetable : []; const reviewSchedules = Array.isArray(value.reviewSchedules) ? value.reviewSchedules : []; const planAdjustments = Array.isArray(value.planAdjustments) ? value.planAdjustments : [];
  const ids = [...tasks, ...plans, ...exams, ...weaknesses, ...studies, ...events, ...timetable].map((item: any) => item?.id).filter(Boolean);
  if (new Set(ids).size !== ids.length) return initial;
  const safe = {
    tasks: tasks.filter((item: any) => item && typeof item.id === "string" && typeof item.title === "string" && validDate(item.due) && Number.isFinite(Number(item.minutes))).map((item: any) => ({ ...item, minutes: Math.max(0, Number(item.minutes)), done: Boolean(item.done) })),
    plans: plans.filter((item: any) => item && typeof item.id === "string" && typeof item.content === "string" && validDate(item.date) && Number.isFinite(Number(item.minutes))).map((item: any) => ({ ...item, minutes: Math.max(0, Number(item.minutes)), done: Boolean(item.done), status: item.status === "cancelled" ? "cancelled" : "planned", fixed: Boolean(item.fixed) })),
    exams: exams.filter((item: any) => item && typeof item.id === "string" && typeof item.name === "string" && validDate(item.date) && isRecord(item.scores)).map((item: any) => ({ ...item, max: Math.max(1, Number(item.max) || 100), scores: Object.fromEntries(Object.entries(item.scores).filter(([, score]) => Number.isFinite(Number(score))).map(([subject, score]) => [subject, Math.max(0, Number(score))])) })),
    weaknesses: weaknesses.filter((item: any) => item && typeof item.id === "string" && typeof item.unit === "string" && validDate(item.review)).map((item: any) => ({ ...item, done: Boolean(item.done), question: typeof item.question === "string" ? item.question : "", answer: typeof item.answer === "string" ? item.answer : "", explanation: typeof item.explanation === "string" ? item.explanation : "", imageData: typeof item.imageData === "string" ? item.imageData : "", difficulty: typeof item.difficulty === "string" ? item.difficulty : "標準", createdAt: validDate(item.createdAt) ? item.createdAt : today, memo: typeof item.memo === "string" ? item.memo : "", history: Array.isArray(item.history) ? item.history.filter((record: any) => record && typeof record.id === "string" && validDate(record.date) && typeof record.correct === "boolean" && Number(record.understanding) >= 1 && Number(record.understanding) <= 5).map((record: any) => ({ ...record, understanding: Number(record.understanding) })) : [] })),
    studies: studies.filter((item: any) => item && typeof item.id === "string" && validDate(item.date) && Number.isFinite(Number(item.minutes))).map((item: any) => ({ ...item, minutes: Math.max(0, Number(item.minutes)), planId: typeof item.planId === "string" ? item.planId : undefined, method: typeof item.method === "string" ? item.method : "", understanding: Number.isFinite(Number(item.understanding)) ? Math.min(5, Math.max(1, Number(item.understanding))) : undefined, difficultPoint: typeof item.difficultPoint === "string" ? item.difficultPoint : "", nextAction: typeof item.nextAction === "string" ? item.nextAction : "" })),
    events: events.filter((item: any) => item && typeof item.id === "string" && typeof item.title === "string" && validDate(item.date)).map((item: any) => ({ ...item, kind: typeof item.kind === "string" ? item.kind : "学校行事", subject: typeof item.subject === "string" ? item.subject : "", note: typeof item.note === "string" ? item.note : "" })),
    timetable: timetable.filter((item: any) => item && typeof item.id === "string" && Number.isInteger(Number(item.day)) && Number(item.day) >= 0 && Number(item.day) <= 4 && Number.isInteger(Number(item.period)) && Number(item.period) >= 1 && Number(item.period) <= 8 && typeof item.subject === "string").map((item: any) => ({ ...item, day: Number(item.day), period: Number(item.period), room: typeof item.room === "string" ? item.room : "", teacher: typeof item.teacher === "string" ? item.teacher : "" })),
    reviewSchedules: reviewSchedules.filter((item: any) => item && typeof item.id === "string" && typeof item.weaknessId === "string" && validDate(item.due) && (item.status === "pending" || item.status === "done")).map((item: any) => ({ ...item })),
    planAdjustments: planAdjustments.filter((item: any) => item && typeof item.id === "string" && validDate(item.createdAt) && Array.isArray(item.before) && Array.isArray(item.after)).map((item: any) => ({ ...item, undone: Boolean(item.undone) })),
    goal: { hours: Math.max(1, Number(value.goal.hours) || 1), score: Math.max(0, Number(value.goal.score) || 0), reflection: typeof value.goal.reflection === "string" ? value.goal.reflection : "", subjectTargets: isRecord(value.goal.subjectTargets) ? Object.fromEntries(Object.entries(value.goal.subjectTargets).filter(([key, score]) => subjects.includes(key) && Number.isFinite(Number(score))).map(([key, score]) => [key, Math.max(0, Number(score))])) : {}, maxDailyMinutes: Math.max(30, Number(value.goal.maxDailyMinutes) || 120) },
  } as Store;
  const existingScheduleWeaknesses = new Set(safe.reviewSchedules.map(schedule => schedule.weaknessId));
  const generatedSchedules = safe.weaknesses.filter(weakness => !existingScheduleWeaknesses.has(weakness.id)).map(weakness => ({ id: `review-${weakness.id}`, weaknessId: weakness.id, due: weakness.review, status: "pending" as const }));
  return isLegacySeed(safe) ? initial : { ...safe, reviewSchedules: [...safe.reviewSchedules, ...generatedSchedules] };
};
const load = (key: string): Store => { try { return cleanLoadedStore(JSON.parse(localStorage.getItem(key) || "null")); } catch { return initial; } };

export default function Home() {
  const auth = useAuth();
  const localMode = false;
  const [data, setData] = useState<Store>(() => load("study-manager-data:guest"));
  const userKey = auth.user ? `study-manager-data:${auth.user.openId}` : "study-manager-data:guest";
  const [hydratedKey, setHydratedKey] = useState("study-manager-data:guest");
  const [serverHydratedFor, setServerHydratedFor] = useState<string | null>(null);
  const [sharedHydratedFor, setSharedHydratedFor] = useState<string | null>(null);
  const updateName = trpc.profile.updateName.useMutation({ onSuccess: () => auth.refresh() });
  const serverData = trpc.study.load.useQuery(undefined, { enabled: Boolean(auth.user) && !localMode, retry: false });
  const saveServerData = trpc.study.save.useMutation({ onSuccess: () => { setNotice("クラウドに保存しました"); window.setTimeout(() => setNotice("自動保存が有効です"), 1800); }, onError: () => setNotice("クラウド保存に失敗しました。通信状態を確認してください") });
  const parentLinks = trpc.parent.list.useQuery(undefined, { enabled: Boolean(auth.user) && !localMode, retry: false, refetchOnWindowFocus: true, refetchInterval: 5000 });
  const sharedStudy = trpc.parent.sharedStudy.useQuery(undefined, { enabled: Boolean(auth.user) && !localMode, retry: false, refetchOnWindowFocus: true, refetchInterval: 5000 });
  const createInvite = trpc.parent.createInvite.useMutation({ onSuccess: () => parentLinks.refetch() });
  const redeemInvite = trpc.parent.redeemInvite.useMutation({ onSuccess: () => { setParentCode(""); parentLinks.refetch(); } });
  const updateSharing = trpc.parent.updateSharing.useMutation({ onSuccess: () => parentLinks.refetch() });
  const [page, setPage] = useState("home");
  const [mobileNav, setMobileNav] = useState(false);
  const [notice, setNotice] = useState("自動保存が有効です");
  const [parentCode, setParentCode] = useState("");
  const [search, setSearch] = useState("");
  const [globalSearch, setGlobalSearch] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [entryRole, setEntryRole] = useState<"student" | "parent">(() => (localStorage.getItem("study-manager-entry-role") as "student" | "parent") || "student");
  const [pendingInviteAttempted, setPendingInviteAttempted] = useState(false);
  const [showTask, setShowTask] = useState(false);
  const [showPlan, setShowPlan] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [editingPlan, setEditingPlan] = useState<Plan | null>(null);
  const [showExam, setShowExam] = useState(false);
  const [showWeak, setShowWeak] = useState(false);
  const [editingWeakness, setEditingWeakness] = useState<Weakness | null>(null);
  const [reviewingWeakness, setReviewingWeakness] = useState<Weakness | null>(null);
  const [showStudy, setShowStudy] = useState(false);
  const [showEvent, setShowEvent] = useState(false);
  const [showTimetable, setShowTimetable] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<{key: "tasks" | "plans" | "exams" | "weaknesses" | "studies" | "events" | "timetable"; id: string} | null>(null);
  const [goalDraft, setGoalDraft] = useState<Goal>(() => ({ ...initial.goal }));
  const [compareCurrentId, setCompareCurrentId] = useState("e1");
  const [comparePreviousId, setComparePreviousId] = useState("e2");
  const [schoolView, setSchoolView] = useState<"list" | "timetable">("list");
  const [analysisPeriod, setAnalysisPeriod] = useState<"week" | "7days" | "month" | "30days" | "custom">("week");
  const [analysisStart, setAnalysisStart] = useState(addDays(today, -6));
  const [analysisEnd, setAnalysisEnd] = useState(today);
  const [timerSeconds, setTimerSeconds] = useState(25 * 60);
  const [timerRunning, setTimerRunning] = useState(false);
  const [reflectionDraft, setReflectionDraft] = useState(data.goal.reflection || "");
  const importRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (auth.user) setPage(entryRole === "parent" ? "parent" : "home");
  }, [auth.user, entryRole]);
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "/" && event.target instanceof HTMLElement && !["INPUT", "TEXTAREA", "SELECT"].includes(event.target.tagName)) { event.preventDefault(); setSearchOpen(true); window.setTimeout(() => document.getElementById("global-search")?.focus(), 0); }
      if (event.key === "Escape") setSearchOpen(false);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);
  useEffect(() => { if (!timerRunning) return; const timer = window.setInterval(() => setTimerSeconds(seconds => { if (seconds <= 1) { setTimerRunning(false); setNotice("集中時間が終わりました。勉強時間を記録しましょう"); return 25 * 60; } return seconds - 1; }), 1000); return () => window.clearInterval(timer); }, [timerRunning]);
  useEffect(() => { if (hydratedKey !== userKey) { setData(load(userKey)); setHydratedKey(userKey); } }, [hydratedKey, userKey]);
  useEffect(() => { if (!auth.user || localMode || !serverData.isSuccess || serverHydratedFor === userKey) return; if (serverData.data) { const restored = cleanLoadedStore(serverData.data); setData(restored); localStorage.setItem(userKey, JSON.stringify(restored)); } setServerHydratedFor(userKey); }, [auth.user, localMode, serverData.data, serverData.isSuccess, serverHydratedFor, userKey]);
  const isParentViewer = Boolean(auth.user && parentLinks.data?.some((link: any) => link.parentId === auth.user?.id && link.status === "active"));
  useEffect(() => {
    const pendingInvite = localStorage.getItem("study-manager-pending-invite");
    if (!auth.user || entryRole !== "parent" || !pendingInvite || pendingInviteAttempted || !parentLinks.isSuccess) return;
    setPendingInviteAttempted(true);
    redeemInvite.mutate({ code: pendingInvite }, { onSuccess: () => { localStorage.removeItem("study-manager-pending-invite"); parentLinks.refetch(); setNotice("招待コードで連携しました"); }, onError: () => { localStorage.removeItem("study-manager-pending-invite"); setNotice("招待コードを確認できませんでした。保護者共有画面から再入力してください"); } });
  }, [auth.user, entryRole, parentLinks.isSuccess, pendingInviteAttempted]);
  useEffect(() => { if (!isParentViewer || !sharedStudy.isSuccess || !sharedStudy.data?.payload || sharedHydratedFor === userKey) return; try { setData(cleanLoadedStore(JSON.parse(sharedStudy.data.payload))); setSharedHydratedFor(userKey); setNotice("共有データを読み込みました"); } catch { setNotice("共有データを読み込めませんでした"); } }, [isParentViewer, sharedStudy.data, sharedStudy.isSuccess, sharedHydratedFor, userKey]);
  useEffect(() => { if (hydratedKey !== userKey) return; localStorage.setItem(userKey, JSON.stringify(data)); if (auth.user && !localMode && !isParentViewer && serverHydratedFor === userKey) saveServerData.mutate({ payload: JSON.stringify(data) }); setNotice(auth.user && !localMode && !isParentViewer && serverHydratedFor === userKey ? "保存中…" : "保存しました"); }, [data, hydratedKey, userKey, auth.user, localMode, isParentViewer, serverHydratedFor]);
  useEffect(() => { setGoalDraft(data.goal); setReflectionDraft(data.goal.reflection || ""); }, [data.goal.hours, data.goal.score, data.goal.reflection]);
  if (auth.loading) return <LoadingScreen />;
  if (!auth.isAuthenticated || !auth.user) return <LoginScreen onLogin={(role) => { localStorage.setItem("study-manager-entry-role", role); setEntryRole(role); startLogin(); }} onLocalLogin={(email, name, role, inviteCode) => { localStorage.setItem("study-manager-entry-role", role); if (inviteCode) localStorage.setItem("study-manager-pending-invite", inviteCode); setEntryRole(role); auth.loginLocal(email, name); }} />;
  const displayName = auth.user.name || "学習ユーザー";

  const todayPlans = data.plans.filter(p => p.date === today);
  const openTasks = data.tasks.filter(t => !t.done);
  const weekMinutes = data.studies.reduce((a, s) => a + s.minutes, 0);
  const overdueTasks = data.tasks.filter(task => !task.done && task.due < today).sort((a, b) => a.due.localeCompare(b.due));
  const upcomingExams = data.exams.filter(exam => exam.date >= today).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 3);
  const todayEvents = data.events.filter(event => event.date === today);
  const dueSchedules = data.reviewSchedules.filter(schedule => schedule.status === "pending" && schedule.due <= today);
  const dueWeaknesses = dueSchedules.map(schedule => data.weaknesses.find(weakness => weakness.id === schedule.weaknessId)).filter(Boolean) as Weakness[];
  const reviewCompleted = data.reviewSchedules.filter(schedule => schedule.status === "done").length;
  const reviewTotal = data.reviewSchedules.length;
  const subjectReviewStats = mainSubjects.map(subject => { const records = data.weaknesses.filter(w => w.subject === subject).flatMap(w => w.history || []); return { subject, total: records.length, correct: records.filter(r => r.correct).length }; }).filter(item => item.total);
  const causeReviewStats = ["知識不足", "計算ミス", "読み違い", "解き方が分からない", "時間不足", "その他"].map(cause => ({ cause, count: data.weaknesses.filter(w => w.cause === cause).length })).filter(item => item.count);
  const studyDateSet = new Set(data.studies.filter(study => study.minutes > 0).map(study => study.date));
  let streakDays = 0;
  const streakCursor = new Date(`${today}T00:00:00`);
  while (studyDateSet.has(streakCursor.toISOString().slice(0, 10))) { streakDays += 1; streakCursor.setDate(streakCursor.getDate() - 1); }
  const goalRate = Math.min(100, Math.round((weekMinutes / (data.goal.hours * 60)) * 100));
  const latest = data.exams[0];
  const previous = data.exams[1];
  const average = latest ? Math.round(Object.values(latest.scores).reduce((a, b) => a + b, 0) / Object.values(latest.scores).length) : 0;
  const activeLink = parentLinks.data?.find((link: any) => link.status === "active");
  const compareCurrent = data.exams.find(e => e.id === compareCurrentId) || latest;
  const comparePrevious = data.exams.find(e => e.id === comparePreviousId) || previous;
  const radarData = mainSubjects.map(subject => ({ subject, 今回: compareCurrent?.scores[subject] || 0, 前回: comparePrevious?.scores[subject] || 0 }));

  const nav = [
    { id: "home", label: "ホーム", icon: LayoutDashboard }, { id: "analytics", label: "学習分析", icon: TrendingUp }, { id: "plans", label: "計画・カレンダー", icon: CalendarDays }, { id: "school", label: "学校生活", icon: CalendarDays }, { id: "tasks", label: "課題・提出物", icon: ListChecks }, { id: "timer", label: "勉強時間", icon: TimerReset }, { id: "exams", label: "テスト・成績", icon: TrendingUp }, { id: "weaknesses", label: "苦手・復習", icon: Target }, { id: "goals", label: "目標・振り返り", icon: Flag }, { id: "reports", label: "レポート", icon: FileText }, { id: "parent", label: "保護者共有", icon: Users }, { id: "settings", label: "設定・データ", icon: Settings },
  ];
  const visibleNav = entryRole === "parent" ? nav.filter(item => item.id === "parent" || item.id === "settings") : nav;
  const update = (next: Partial<Store>) => setData(d => ({ ...d, ...next }));
  const loadSample = () => { update(sampleData); setNotice("サンプルデータを読み込みました"); };
  const toggle = (key: "tasks" | "plans", id: string) => update({ [key]: data[key].map((x: any) => x.id === id ? { ...x, done: !x.done } : x) } as any);
  const remove = (key: "tasks" | "plans" | "exams" | "weaknesses" | "studies" | "events" | "timetable", id: string) => setPendingDelete({ key, id });
  const confirmRemove = () => { if (!pendingDelete) return; const next = { [pendingDelete.key]: (data[pendingDelete.key] as any[]).filter(x => x.id !== pendingDelete.id) } as any; if (pendingDelete.key === "weaknesses") next.reviewSchedules = data.reviewSchedules.filter(schedule => schedule.weaknessId !== pendingDelete.id); update(next); setPendingDelete(null); setNotice("削除しました"); };
  const saveTask = (draft: Omit<Task, "id" | "done">) => { update({ tasks: editingTask ? data.tasks.map(item => item.id === editingTask.id ? { ...item, ...draft } : item) : [...data.tasks, { ...draft, id: uid(), done: false }] }); setEditingTask(null); setShowTask(false); setNotice("課題を保存しました"); };
  const savePlan = (draft: Omit<Plan, "id" | "done">) => { update({ plans: editingPlan ? data.plans.map(item => item.id === editingPlan.id ? { ...item, ...draft } : item) : [...data.plans, { ...draft, id: uid(), done: false }] }); setEditingPlan(null); setShowPlan(false); setNotice("計画を保存しました"); };
  const exportData = () => { const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "study-manager-backup.json"; a.click(); setNotice("バックアップを書き出しました"); };
  const printReport = () => { setNotice("印刷画面を開いています"); window.setTimeout(() => window.print(), 50); };
  const importData = async (file?: File) => { if (!file) return; try { const raw = JSON.parse(await file.text()); const restored = cleanLoadedStore(raw); if (restored === initial && JSON.stringify(raw) !== JSON.stringify(initial)) throw new Error("invalid"); if (!confirm("現在のデータをバックアップ内容で置き換えますか？")) return; update(restored); setNotice("バックアップを検証して復元しました"); } catch { setNotice("復元できないファイルです。JSON形式・必須項目・重複IDを確認してください"); } finally { if (importRef.current) importRef.current.value = ""; } };
  const normalizeSearch = (value: unknown) => String(value ?? "").normalize("NFKC").replace(/\s+/g, "").toLocaleLowerCase();
  const searchQuery = normalizeSearch(search);
  const globalQuery = normalizeSearch(globalSearch);
  const filteredTasks = data.tasks.filter(t => normalizeSearch(`${t.title}${t.subject}${t.kind}`).includes(searchQuery));
  const globalResults = globalQuery ? [
    ...data.tasks.filter(item => normalizeSearch(`${item.title} ${item.subject} ${item.kind} ${item.due}`).includes(globalQuery)).map(item => ({ kind: "課題", title: item.title, meta: `${item.subject} ・ ${item.due.replaceAll("-", "/")}`, page: "tasks" })),
    ...data.plans.filter(item => normalizeSearch(`${item.content} ${item.subject} ${item.priority} ${item.date}`).includes(globalQuery)).map(item => ({ kind: "計画", title: item.content, meta: `${item.subject} ・ ${item.date.replaceAll("-", "/")}`, page: "plans" })),
    ...data.exams.filter(item => normalizeSearch(`${item.name} ${item.term} ${item.date} ${Object.keys(item.scores).join(" ")}`).includes(globalQuery)).map(item => ({ kind: "テスト", title: item.name, meta: `${item.term} ・ ${item.date.replaceAll("-", "/")}`, page: "exams" })),
    ...data.weaknesses.filter(item => normalizeSearch(`${item.unit} ${item.subject} ${item.cause} ${item.review}`).includes(globalQuery)).map(item => ({ kind: "復習", title: item.unit, meta: `${item.subject} ・ 復習日 ${item.review.replaceAll("-", "/")}`, page: "weaknesses" })),
    ...data.studies.filter(item => normalizeSearch(`${item.subject} ${item.note} ${item.date}`).includes(globalQuery)).map(item => ({ kind: "勉強記録", title: `${item.subject}を${item.minutes}分`, meta: `${item.date.replaceAll("-", "/")} ・ ${item.note || "メモなし"}`, page: "timer" })),
    ...data.events.filter(item => normalizeSearch(`${item.title} ${item.kind} ${item.subject} ${item.note} ${item.date}`).includes(globalQuery)).map(item => ({ kind: "学校予定", title: item.title, meta: `${item.kind} ・ ${item.date.replaceAll("-", "/")}`, page: "school" })),
    ...data.timetable.filter(item => normalizeSearch(`${item.subject} ${item.room} ${item.teacher}`).includes(globalQuery)).map(item => ({ kind: "時間割", title: `${["月", "火", "水", "木", "金"][item.day]}曜 ${item.period}限 ${item.subject}`, meta: `${item.room || "教室未設定"} ・ ${item.teacher || "担当未設定"}`, page: "school" })),
    ...visibleNav.filter(item => normalizeSearch(`${item.label} ${item.id}`).includes(globalQuery)).map(item => ({ kind: "画面", title: item.label, meta: "画面を開く", page: item.id })),
  ].slice(0, 12) : [];
  const quickAdd = (kind: "plan" | "task" | "study" | "exam" | "weakness") => {
    if (kind === "plan") { setPage("plans"); setEditingPlan(null); setShowPlan(true); }
    if (kind === "task") { setPage("tasks"); setEditingTask(null); setShowTask(true); }
    if (kind === "study") { setPage("timer"); setShowStudy(true); }
    if (kind === "exam") { setPage("exams"); setShowExam(true); }
    if (kind === "weakness") { setPage("weaknesses"); setShowWeak(true); }
  };
  const chartData = mainSubjects.map(subject => ({ subject, minutes: data.studies.filter(s => s.subject === subject).reduce((a, s) => a + s.minutes, 0), latest: latest?.scores[subject] || 0, previous: previous?.scores[subject] || 0 }));

  const completeReview = (weakness: Weakness, result: { correct: boolean; understanding: number; seconds?: number; memo?: string }) => {
    const current = data.reviewSchedules.find(schedule => schedule.weaknessId === weakness.id && schedule.status === "pending" && schedule.due <= today) || data.reviewSchedules.find(schedule => schedule.weaknessId === weakness.id && schedule.status === "pending");
    const nextDays = !result.correct || result.understanding <= 2 ? 1 : result.understanding === 3 ? 3 : result.understanding === 4 ? 7 : 14;
    const next = new Date(`${today}T00:00:00`); next.setDate(next.getDate() + nextDays); const nextDate = next.toISOString().slice(0, 10);
    const history: ReviewRecord = { id: uid(), date: today, correct: result.correct, understanding: result.understanding, seconds: result.seconds, memo: result.memo };
    update({ weaknesses: data.weaknesses.map(item => item.id === weakness.id ? { ...item, review: nextDate, done: false, history: [...(item.history || []), history] } : item), reviewSchedules: data.reviewSchedules.map(schedule => schedule.id === current?.id ? { ...schedule, status: "done" as const, completedAt: today } : schedule).concat({ id: uid(), weaknessId: weakness.id, due: nextDate, status: "pending" as const }) });
    setReviewingWeakness(null); setNotice(`復習結果を保存しました。次回は${nextDays}日後です`);
  };
  const autoAdjustPlans = () => {
    const candidates = data.plans.filter(plan => !plan.done && plan.status !== "cancelled" && !plan.fixed && plan.date < today);
    if (!candidates.length) { setNotice("自動調整できる未完了計画はありません"); return; }
    const dailyLimit = Math.max(30, Number((data.goal as Goal & {maxDailyMinutes?: number}).maxDailyMinutes) || 120);
    const occupied: Record<string, number> = {};
    data.plans.filter(plan => !candidates.some(candidate => candidate.id === plan.id) && plan.status !== "cancelled").forEach(plan => { occupied[plan.date] = (occupied[plan.date] || 0) + plan.minutes; });
    const nextDates: Record<string, string> = {};
    candidates.sort((a, b) => (a.priority === "高" ? -1 : 1) - (b.priority === "高" ? -1 : 1)).forEach(candidate => { let cursor = today; for (let i = 0; i < 30; i += 1) { const blocked = data.events.some(event => event.date === cursor && event.kind === "学校行事"); if (!blocked && (occupied[cursor] || 0) + candidate.minutes <= dailyLimit) { nextDates[candidate.id] = cursor; occupied[cursor] = (occupied[cursor] || 0) + candidate.minutes; break; } cursor = addDays(cursor, 1); } });
    const nextPlans = data.plans.map(plan => nextDates[plan.id] ? { ...plan, date: nextDates[plan.id] } : plan);
    const moved = candidates.filter(candidate => nextDates[candidate.id]);
    if (!moved.length) { setNotice(`1日${dailyLimit}分の上限内に再配置できませんでした`); return; }
    const confirmed = window.confirm(`${moved.length}件を1日${dailyLimit}分以内・学校行事のない日に再配置します。固定予定などは変更しません。適用しますか？`);
    if (!confirmed) return;
    update({ plans: nextPlans, planAdjustments: [...data.planAdjustments, { id: uid(), createdAt: today, reason: "日別上限と学校行事を考慮した未完了計画の再配置", before: data.plans, after: nextPlans }] });
    setNotice("計画の調整を適用しました");
  };
  const undoLastAdjustment = () => { const last = [...data.planAdjustments].reverse().find(adjustment => !adjustment.undone); if (!last) { setNotice("取り消せる計画変更はありません"); return; } if (!window.confirm("直前の計画変更を取り消しますか？")) return; update({ plans: last.before, planAdjustments: data.planAdjustments.map(adjustment => adjustment.id === last.id ? { ...adjustment, undone: true } : adjustment) }); setNotice("計画変更を取り消しました"); };
  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? "open" : ""}`}>
      <div className="brand"><div className="brand-mark">S</div><div><strong>Study Manager</strong><small>学習管理</small></div><button className="close-nav" onClick={() => setMobileNav(false)}><X size={18}/></button></div>
      <div className="profile"><div className="avatar">{displayName.slice(0, 1)}</div><div><b>{displayName}</b><span>Study Manager ユーザー</span></div><ShieldCheck size={17} className="verified"/></div>
      <nav>{visibleNav.map(item => { const Icon = item.icon; return <button key={item.id} className={page === item.id ? "active" : ""} onClick={() => { setPage(item.id); setMobileNav(false); }}><Icon size={18}/><span>{item.label}</span>{item.id === "tasks" && openTasks.length > 0 && <em>{openTasks.length}</em>}</button>; })}</nav>
      <div className="sidebar-bottom"><div className="mini-progress"><div className="mini-head"><span>今週の目標</span><b>{goalRate}%</b></div><div className="progress"><i style={{ width: `${goalRate}%` }}/></div><small>{Math.floor(weekMinutes / 60)}時間{weekMinutes % 60}分 / {data.goal.hours}時間</small></div><div className="privacy"><ShieldCheck size={15}/><span>データはあなたの管理下</span></div></div>
    </aside>
    {mobileNav && <div className="scrim" onClick={() => setMobileNav(false)}/>} 
    <main className="main-content">
      <header className="topbar"><button className="mobile-menu" onClick={() => setMobileNav(true)}><Menu size={21}/></button><div className="crumb">Study Manager <ChevronRight size={14}/> <b>{visibleNav.find(n => n.id === page)?.label || "保護者ホーム"}</b></div><div className="top-actions"><div className="save-status"><span className="status-dot"/> {notice}</div><button className={`icon-btn ${searchOpen ? "active" : ""}`} title="検索（/キー）" aria-label="検索を開く" onClick={() => { setSearchOpen(open => !open); window.setTimeout(() => document.getElementById("global-search")?.focus(), 0); }}><Search size={18}/></button><button className="top-avatar" aria-label="設定を開く" onClick={() => setPage("settings")}>{displayName.slice(0, 1)}</button></div></header>
          {searchOpen && <div className="global-search-panel"><div className="global-search-input"><Search size={17}/><input id="global-search" autoFocus value={globalSearch} onChange={e => setGlobalSearch(e.target.value)} placeholder="課題・計画・テスト・復習を検索"/><kbd>Esc</kbd></div>{globalQuery && <div className="global-results">{globalResults.length ? globalResults.map((result, index) => <button className="global-result" key={`${result.kind}-${result.title}-${index}`} onClick={() => { setPage(result.page); setSearchOpen(false); setGlobalSearch(""); }}><span className="result-kind">{result.kind}</span><span><b>{result.title}</b><small>{result.meta}</small></span><ChevronRight size={15}/></button>) : <div className="global-empty">一致する記録がありません。別の言葉で試してください。</div>}</div>}<div className="search-hint">ヒント：キーボードの <kbd>/</kbd> でいつでも検索できます</div></div>}
      <div className="page-wrap">
        {page === "analytics" && <AnalyticsDashboard data={data} period={analysisPeriod} start={analysisStart} end={analysisEnd} onPeriodChange={setAnalysisPeriod} onStartChange={setAnalysisStart} onEndChange={setAnalysisEnd} onNavigate={setPage} onAutoAdjust={autoAdjustPlans} onUndoAdjustment={undoLastAdjustment} />}
        {page === "home" && <Dashboard data={data} displayName={displayName} todayPlans={todayPlans} openTasks={openTasks} goalRate={goalRate} average={average} chartData={chartData} onNavigate={setPage} onToggle={(id: string) => toggle("plans", id)} onQuickAdd={quickAdd} overdueTasks={overdueTasks} upcomingExams={upcomingExams} todayEvents={todayEvents} todayReviews={dueWeaknesses} streakDays={streakDays} />}
        {page === "school" && <SchoolCalendar data={data} view={schoolView} onViewChange={setSchoolView} onAddEvent={() => setShowEvent(true)} onAddTimetable={() => setShowTimetable(true)} onDeleteEvent={(id: string) => remove("events", id)} onDeleteTimetable={(id: string) => remove("timetable", id)} />}
        {page === "plans" && <Section title="計画・カレンダー" eyebrow="PLAN YOUR WEEK" subtitle="テスト日から逆算して、今日の一歩を決めましょう。" action={<button className="primary" onClick={() => { setEditingPlan(null); setShowPlan(true); }}><Plus size={17}/> 計画を追加</button>}><div className="week-strip">{["月 13", "火 14", "水 15", "木 16", "金 17", "土 18", "日 19"].map((d, i) => <div className={i === 4 ? "today" : ""} key={d}><small>10月</small><b>{d.split(" ")[1]}</b><span>{i === 4 ? "今日" : d.split(" ")[0]}</span></div>)}</div><div className="list-card">{data.plans.map(p => <div className="list-row" key={p.id}><button className={`check ${p.done ? "checked" : ""}`} onClick={() => toggle("plans", p.id)}>{p.done && <Check size={14}/>}</button><div className="row-main"><b>{p.content}</b><span>{p.subject} ・ {p.minutes}分 ・ 優先度 {p.priority}</span></div><time>{p.date === today ? "今日" : p.date.slice(5).replace("-", "/")}</time><button className="outline row-edit" onClick={() => { setEditingPlan(p); setShowPlan(true); }}>編集</button><button className="text-danger" onClick={() => remove("plans", p.id)}>削除</button></div>)}</div></Section>}
        {page === "tasks" && <Section title="課題・提出物" eyebrow="TASKS & DEADLINES" subtitle="学校・塾・自主学習をまとめて、期限を見落とさない。" action={<button className="primary" onClick={() => { setEditingTask(null); setShowTask(true); }}><Plus size={17}/> 課題を追加</button>}><div className="toolbar"><div className="search-box"><Search size={17}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="課題名・教科で検索"/></div><span className="muted">未完了 {openTasks.length}件 / 全{data.tasks.length}件</span></div><div className="list-card">{filteredTasks.map(t => <div className="list-row" key={t.id}><button className={`check ${t.done ? "checked" : ""}`} onClick={() => toggle("tasks", t.id)}>{t.done && <Check size={14}/>}</button><div className="row-main"><b className={t.done ? "done-text" : ""}>{t.title}</b><span><label className="tag">{t.kind}</label> {t.subject} ・ {t.minutes}分</span></div><time className={t.due < today && !t.done ? "overdue" : ""}>{t.due.replaceAll("-", "/")}</time><button className="outline row-edit" onClick={() => { setEditingTask(t); setShowTask(true); }}>編集</button><button className="text-danger" onClick={() => remove("tasks", t.id)}>削除</button></div>)}</div></Section>}
        {page === "timer" && <Section title="勉強時間" eyebrow="FOCUS LOG" subtitle="記録が積み重なると、自分に合う勉強のリズムが見えてきます。" action={<button className="primary" onClick={() => setShowStudy(true)}><Plus size={17}/> 記録を追加</button>}><div className="focus-hero"><div className="timer-ring"><span>{String(Math.floor(timerSeconds / 60)).padStart(2, "0")}:{String(timerSeconds % 60).padStart(2, "0")}</span><small>{timerRunning ? "集中中" : "集中タイマー"}</small></div><div><span className="eyebrow">TODAY'S FOCUS</span><h2>{timerRunning ? "今は集中する時間です。" : "短い時間から始めましょう。"}</h2><p>今週は{weekMinutes}分を記録中。タイマー終了後に勉強時間を記録できます。</p><div className="timer-actions"><button className="primary" type="button" onClick={() => setTimerRunning(running => !running)}>{timerRunning ? <Pause size={16}/> : <Play size={16}/>} {timerRunning ? "一時停止" : "開始する"}</button><button className="outline" type="button" onClick={() => { setTimerRunning(false); setTimerSeconds(25 * 60); }}><RotateCcw size={16}/> リセット</button><button className="outline" type="button" onClick={() => setShowStudy(true)}><Clock3 size={16}/> 勉強を記録する</button></div></div></div><div className="chart-card"><div className="card-title"><div><b>教科別の勉強時間</b><span>今週の記録</span></div><span className="metric">{weekMinutes}<small>分</small></span></div><div className="chart-box"><ResponsiveContainer width="100%" height={250}><BarChart data={chartData}><CartesianGrid vertical={false} stroke="#e6ebf1"/><XAxis dataKey="subject" tickLine={false} axisLine={false}/><YAxis tickLine={false} axisLine={false}/><Tooltip/><Bar dataKey="minutes" fill="#183b67" radius={[5,5,0,0]} /></BarChart></ResponsiveContainer></div></div><div className="list-card">{data.studies.slice().reverse().map(s => <div className="list-row" key={s.id}><div className="study-icon"><Clock3 size={16}/></div><div className="row-main"><b>{s.subject}を{Math.floor(s.minutes / 60) > 0 ? `${Math.floor(s.minutes / 60)}時間` : ""}{s.minutes % 60}分</b><span>{s.date} ・ {s.note || "メモなし"}</span></div><button className="text-danger" onClick={() => remove("studies", s.id)}>削除</button></div>)}</div></Section>}
        {page === "exams" && <Section title="テスト・成績" eyebrow="EXAM RESULTS" subtitle="2つのテストを選ぶと、5教科の変化を五角形で比べられます。" action={<button className="primary" onClick={() => setShowExam(true)}><Plus size={17}/> テストを追加</button>}><div className="metric-grid"><Metric label="最新の平均点" value={`${average}点`} delta={latest && previous ? `前回比 ${average - Math.round(Object.values(previous.scores).reduce((a,b)=>a+b,0)/Object.values(previous.scores).length) >= 0 ? "+" : ""}${average - Math.round(Object.values(previous.scores).reduce((a,b)=>a+b,0)/Object.values(previous.scores).length)}点` : ""} positive/><Metric label="5教科合計" value={`${latest ? Object.values(latest.scores).reduce((a,b)=>a+b,0) : 0}点`} delta="満点 500点"/><Metric label="目標まで" value={`${Math.max(0, data.goal.score - (latest ? Object.values(latest.scores).reduce((a,b)=>a+b,0) : 0))}点`} delta={`目標 ${data.goal.score}点`}/></div><div className="compare-card"><div className="card-title"><div><b>テストを選んで比較</b><span>点数が増えても、いつでも2回を選択できます。</span></div><TrendingUp size={18} className="panel-icon"/></div><div className="compare-controls"><label>今回<select value={compareCurrent?.id || ""} onChange={e => setCompareCurrentId(e.target.value)}>{data.exams.map(e => <option key={e.id} value={e.id}>{e.name}（{e.date}）</option>)}</select></label><span className="compare-arrow">→</span><label>前回<select value={comparePrevious?.id || ""} onChange={e => setComparePreviousId(e.target.value)}>{data.exams.map(e => <option key={e.id} value={e.id}>{e.name}（{e.date}）</option>)}</select></label></div><div className="radar-wrap"><ResponsiveContainer width="100%" height={330}><RadarChart data={radarData} cx="50%" cy="50%" outerRadius="72%"><PolarGrid stroke="#dfe6ee"/><PolarAngleAxis dataKey="subject" tick={{fill:"#657086",fontSize:12}}/><PolarRadiusAxis angle={90} domain={[0,100]} tick={{fill:"#9aa5b3",fontSize:9}}/><Radar name={compareCurrent?.name || "今回"} dataKey="今回" stroke="#183b67" fill="#183b67" fillOpacity={0.24} strokeWidth={2}/><Radar name={comparePrevious?.name || "前回"} dataKey="前回" stroke="#c28b35" fill="#c28b35" fillOpacity={0.12} strokeWidth={2} strokeDasharray="5 4"/><Legend/></RadarChart></ResponsiveContainer></div><div className="compare-note"><b>{compareCurrent?.name || "今回"}</b> と <b>{comparePrevious?.name || "前回"}</b> の差を確認できます。外側に広がるほど点数が高く、教科ごとの伸び・下がりが見つけやすくなります。</div></div><div className="list-card">{data.exams.map(e => <div className="list-row" key={e.id}><div className="exam-date">{e.date.slice(5).replace("-", "/")}</div><div className="row-main"><b>{e.name}</b><span>{e.term} ・ 5教科合計 {Object.values(e.scores).reduce((a,b)=>a+b,0)} / {e.max * Object.keys(e.scores).length}点</span></div><button className="text-danger" onClick={() => remove("exams", e.id)}>削除</button></div>)}</div></Section>}
        {page === "weaknesses" && <Section title="間違いノート・復習" eyebrow="MISTAKE NOTE & REVIEW" subtitle="間違えた問題を残し、解き直した結果から次の復習日を自動で決めます。" action={<button className="primary" onClick={() => { setEditingWeakness(null); setShowWeak(true); }}><Plus size={17}/> 問題を登録</button>}><div className="review-summary"><div><span>今日の復習</span><b>{dueWeaknesses.length}件</b><small>期限超過を含む</small></div><div><span>登録問題</span><b>{data.weaknesses.length}件</b><small>過去の履歴を保持</small></div><div><span>完了率</span><b>{reviewTotal ? `${Math.round((reviewCompleted / reviewTotal) * 100)}%` : "データ不足"}</b><small>復習予定ベース</small></div></div><div className="review-analysis"><div><b>教科別の正答率</b>{subjectReviewStats.length ? subjectReviewStats.map(item => <span key={item.subject}>{item.subject} <strong>{Math.round((item.correct / item.total) * 100)}%</strong> <small>（{item.total}回）</small></span>) : <small>復習結果が蓄積されると表示します。</small>}</div><div><b>間違いの原因</b>{causeReviewStats.length ? causeReviewStats.map(item => <span key={item.cause}>{item.cause} <strong>{item.count}件</strong></span>) : <small>問題を登録すると集計します。</small>}</div></div><div className="review-filter-row"><b>今日やる復習</b><span>復習予定日が今日以前の問題</span><select onChange={e => { const subject = e.target.value; const filtered = subject ? data.weaknesses.filter(w => w.subject === subject && dueSchedules.some(s => s.weaknessId === w.id)) : dueWeaknesses; setReviewingWeakness(filtered[0] || null); }} defaultValue=""><option value="">教科で絞り込み（開始）</option>{subjects.map(subject => <option key={subject}>{subject}</option>)}</select></div><div className="list-card review-list">{dueWeaknesses.length ? dueWeaknesses.map(weakness => <div className="list-row" key={weakness.id}><div className="review-state">復習</div><div className="row-main"><b>{weakness.unit}</b><span>{weakness.subject} ・ 原因：{weakness.cause} ・ 予定 {weakness.review}</span></div><button className="primary small-button" onClick={() => setReviewingWeakness(weakness)}>復習する</button><button className="text-danger" onClick={() => remove("weaknesses", weakness.id)}>削除</button></div>) : <div className="empty-state"><Target size={24}/><b>今日の復習はありません</b><span>問題を登録すると、初回は翌日に復習予定が作られます。</span></div>}</div><div className="section-label review-all-label"><b>登録済みの間違いノート</b><span>教科・単元・原因をあとから検索できます。</span></div><div className="list-card">{data.weaknesses.map(w => <div className="list-row" key={w.id}><div className="study-icon"><Target size={16}/></div><div className="row-main"><b>{w.unit}</b><span>{w.subject} ・ {w.difficulty || "標準"} ・ 復習回数 {(w.history || []).length}回 ・ 次回 {w.review}</span></div><button className="outline row-edit" onClick={() => { setEditingWeakness(w); setShowWeak(true); }}>編集</button><button className="outline row-edit" onClick={() => setReviewingWeakness(w)}>復習</button></div>)}</div></Section>}
        {page === "goals" && <Section title="目標・振り返り" eyebrow="GOALS & REFLECTION" subtitle="自分で決めた目標を、今の自分に合わせて更新できます。"><div className="goal-panel"><div><span className="eyebrow">THIS MONTH</span><h2>次のテストで、あと一歩。</h2><p>数字を入力して「目標を保存」を押すと、ホームの進捗に反映されます。</p></div><div className="goal-fields"><label>目標点<input type="number" min="0" max="900" value={goalDraft.score} onChange={e => setGoalDraft({...goalDraft, score: Number(e.target.value)})}/><small>点</small></label><label>週の勉強時間<input type="number" min="1" max="168" value={goalDraft.hours} onChange={e => setGoalDraft({...goalDraft, hours: Number(e.target.value)})}/><small>時間</small></label><label>1日の上限<input type="number" min="30" max="720" value={goalDraft.maxDailyMinutes || 120} onChange={e => setGoalDraft({...goalDraft, maxDailyMinutes: Number(e.target.value) || 120})}/><small>分</small></label><div className="subject-targets"><b>教科別目標点（任意）</b><div>{mainSubjects.map(subject => <label key={subject}>{subject}<input type="number" min="0" max="100" value={goalDraft.subjectTargets?.[subject] ?? ""} placeholder="未設定" onChange={e => setGoalDraft({...goalDraft, subjectTargets: {...(goalDraft.subjectTargets || {}), [subject]: Number(e.target.value) || 0}})}/></label>)}</div></div><button className="primary goal-save" type="button" onClick={() => { update({goal: {...data.goal, score: Math.max(0, goalDraft.score), hours: Math.max(1, goalDraft.hours), reflection: reflectionDraft, subjectTargets: goalDraft.subjectTargets || {}}}); setNotice("目標を保存しました"); }}>目標を保存</button></div></div><div className="reflection"><div className="section-label"><b>今週の振り返り</b><span>短くても、書くと次の計画に活きます。</span></div><textarea placeholder="できたこと、次に改善したいことを書いてみましょう。" value={reflectionDraft} onChange={e => setReflectionDraft(e.target.value)} /><button className="outline" type="button" onClick={() => { update({goal: {...data.goal, reflection: reflectionDraft}}); setNotice("振り返りを保存しました"); }}>振り返りを保存</button></div></Section>}
        {page === "reports" && <Section title="レポート" eyebrow="WEEKLY REPORT" subtitle="今週の記録を、家庭で一緒に振り返るための一枚にまとめます。" action={<button className="primary" type="button" onClick={printReport}><FileText size={17}/> 印刷する</button>}><div className="report-paper"><div className="report-header"><div><span className="eyebrow">STUDY MANAGER</span><h2>{displayName}さんの学習レポート</h2><p>今週の記録</p></div><div className="report-mark">S</div></div><div className="report-stats"><div><span>勉強時間</span><b>{Math.floor(weekMinutes / 60)}時間{weekMinutes % 60}分</b></div><div><span>課題完了</span><b>{data.tasks.filter(t => t.done).length} / {data.tasks.length}件</b></div><div><span>最新平均点</span><b>{average}点</b></div></div><div className="report-section"><h3>今週の記録</h3><table><thead><tr><th>教科</th><th>勉強時間</th><th>最新点</th><th>次の一歩</th></tr></thead><tbody>{chartData.map(c => <tr key={c.subject}><td>{c.subject}</td><td>{c.minutes}分</td><td>{c.latest ? `${c.latest}点` : "—"}</td><td>{c.minutes < 30 ? "短時間から始める" : "この調子で続ける"}</td></tr>)}</tbody></table></div><div className="report-section"><h3>復習メモ</h3><p>{data.weaknesses.filter(w => !w.done).map(w => `${w.subject}：${w.unit}`).join("、") || "今週の復習項目はありません。"}</p></div><div className="report-footer">Study Manager ・ 自分の学びを、自分で見えるように。</div></div></Section>}
        {page === "parent" && <Section title="保護者共有" eyebrow="PARENT SPACE" subtitle="保護者は別アカウントでログインし、招待コードで安全に連携します。"><div className="parent-hero"><div className="parent-avatar">保</div><div><span className="eyebrow">{activeLink ? "CONNECTED" : "NOT CONNECTED"}</span><h2>{activeLink ? "保護者アカウントと連携中" : "保護者と連携する"}</h2><p>{activeLink ? "共有設定に応じた情報だけが表示されます。" : "生徒のパスワードを共有せずに連携できます。"}</p></div><span className="connected"><span/> {activeLink ? "連携中" : "未連携"}</span></div><div className="invite-panel"><div className="section-label"><b>アカウント連携</b><span>招待コードは一度だけ使えます</span></div>{activeLink ? <p className="connected-copy">保護者アカウントとの連携が完了しています。共有する内容は下の設定から変更できます。</p> : <div className="invite-actions"><button className="primary" type="button" onClick={() => createInvite.mutate()}>{createInvite.isPending ? "発行中…" : "招待コードを発行"}</button><input value={parentCode} onChange={e => setParentCode(e.target.value.toUpperCase())} placeholder="例：AB12-CD34" maxLength={9}/><button className="outline" type="button" onClick={() => redeemInvite.mutate({ code: parentCode })} disabled={parentCode.length !== 9}>コードで連携</button></div>}{createInvite.data?.inviteCode && !activeLink && <div className="invite-code">保護者に伝えるコード <b>{createInvite.data.inviteCode}</b></div>}{redeemInvite.error && <p className="form-error">{redeemInvite.error.message}</p>}</div><div className="share-card"><div className="section-label"><div><b>共有範囲</b><span>生徒が許可した項目だけが表示されます</span></div><button className="outline" type="button" onClick={() => parentLinks.refetch()}>状態を更新</button></div>{!activeLink && !isParentViewer && <p className="share-help">保護者が招待コードを入力すると設定できます。連携後もオフのままなら「状態を更新」を押してください。</p>}{["今週の計画と課題の進捗", "勉強時間の合計", "テスト結果と成績推移", "苦手単元と復習状況"].map((x, i) => <label className="switch-row" key={x}><span><b>{x}</b><small>{i === 2 ? "点数の詳細を含む" : "保護者に表示する"}</small></span><input type="checkbox" checked={Boolean(activeLink && [activeLink.sharePlan, activeLink.shareStudy, activeLink.shareScores, activeLink.shareWeaknesses][i])} onChange={e => { if (!activeLink || isParentViewer) return; const keys = ["sharePlan", "shareStudy", "shareScores", "shareWeaknesses"] as const; updateSharing.mutate({ linkId: activeLink.id, [keys[i]]: e.target.checked ? 1 : 0 }); }} disabled={!activeLink || isParentViewer}/><i/></label>)}<div className="privacy-note"><ShieldCheck size={17}/><span>パスワードを共有せず、保護者専用の権限で安全に閲覧できます。</span></div></div><div className="comment-box"><div className="section-label"><b>応援メッセージ</b><span>{activeLink ? "連携後にコメントを利用できます" : "保護者連携後に利用できます"}</span></div><div className="comment-input"><input placeholder="返信を書く…" disabled={!activeLink}/><button className="primary" disabled={!activeLink}>送信</button></div></div></Section>}
        {page === "settings" && <Section title="設定・データ" eyebrow="SETTINGS & DATA" subtitle="名前、保存状態、バックアップを管理します。"><form className="name-card" onSubmit={e => { e.preventDefault(); const name = String(new FormData(e.currentTarget).get("name") || "").trim(); if (name) { if (localMode && auth.user?.email) auth.loginLocal(auth.user.email, name); else updateName.mutate({ name }); } }}><div><b>表示名</b><p>家族との共有画面にも表示される名前です。</p></div><input name="name" defaultValue={displayName} maxLength={80}/><button className="primary" type="submit">{updateName.isPending ? "保存中…" : "名前を保存"}</button></form><div className="setting-card sample-card"><div className="setting-icon"><FileText size={18}/></div><div><b>使い方を試す</b><p>空の画面にサンプルデータを読み込みます。あとで削除できます。</p></div><button className="outline" type="button" onClick={loadSample}>サンプルを読み込む</button></div><div className="settings-grid"><div className="setting-card"><div className="setting-icon"><Download size={18}/></div><div><b>バックアップを書き出す</b><p>学習データをJSON形式で保存します。</p></div><button className="outline" type="button" onClick={exportData}>書き出す</button></div><div className="setting-card"><div className="setting-icon"><Upload size={18}/></div><div><b>バックアップを復元する</b><p>復元前に現在の状態を確認します。</p></div><input ref={importRef} type="file" accept="application/json,.json" hidden onChange={e => importData(e.target.files?.[0])}/><button className="outline" type="button" onClick={() => importRef.current?.click()}>ファイル選択</button></div><div className="setting-card"><div className="setting-icon"><ShieldCheck size={18}/></div><div><b>データ保護</b><p>ログイン中のアカウント専用に保存しています。</p></div><span className="status-pill">正常</span></div><div className="setting-card"><div className="setting-icon"><Users size={18}/></div><div><b>ログイン中のアカウント</b><p>{auth.user.email || auth.user.openId}</p></div><button className="outline" type="button" onClick={() => auth.logout()}>ログアウト</button></div></div><div className="empty-note"><CircleHelp size={18}/><span>学習データはログインユーザーごとに分離して保存します。保護者共有では、許可した項目だけを表示する設計にします。</span></div></Section>}
      </div>
    </main>
    {showTask && <TaskModal initial={editingTask} onClose={() => { setEditingTask(null); setShowTask(false); }} onSave={saveTask}/>} 
    {showPlan && <PlanModal initial={editingPlan} onClose={() => { setEditingPlan(null); setShowPlan(false); }} onSave={savePlan}/>} 
    {showExam && <ExamModal onClose={() => setShowExam(false)} onSave={(e: Exam) => { update({exams: [e, ...data.exams]}); setShowExam(false); }}/>} 
    {reviewingWeakness && <ReviewModal weakness={reviewingWeakness} onClose={() => setReviewingWeakness(null)} onComplete={(result) => completeReview(reviewingWeakness, result)} />}
    {showWeak && <WeakModal initial={editingWeakness} onClose={() => { setEditingWeakness(null); setShowWeak(false); }} onSave={(w: Omit<Weakness, "id" | "done">) => { if (editingWeakness) { update({ weaknesses: data.weaknesses.map(item => item.id === editingWeakness.id ? { ...item, ...w, id: item.id, done: item.done, history: item.history || [] } : item), reviewSchedules: data.reviewSchedules.map(schedule => schedule.weaknessId === editingWeakness.id && schedule.status === "pending" ? { ...schedule, due: w.review } : schedule) }); setNotice("問題を更新しました"); } else { const id = uid(); update({ weaknesses: [...data.weaknesses, { ...w, id, done: false, createdAt: today, history: [] }], reviewSchedules: [...data.reviewSchedules, { id: uid(), weaknessId: id, due: w.review, status: "pending" }] }); setNotice("問題を登録しました。初回の復習予定を作成しました"); } setEditingWeakness(null); setShowWeak(false); }}/>} 
    {showEvent && <EventModal onClose={() => setShowEvent(false)} onSave={(event: Omit<SchoolEvent, "id">) => { update({ events: [...data.events, { ...event, id: uid() }] }); setShowEvent(false); setNotice("学校予定を保存しました"); }} />}
    {showTimetable && <TimetableModal onClose={() => setShowTimetable(false)} onSave={(entry: Omit<TimetableEntry, "id">) => { update({ timetable: [...data.timetable.filter(x => !(x.day === entry.day && x.period === entry.period)), { ...entry, id: uid() }] }); setShowTimetable(false); setNotice("時間割を保存しました"); }} />}
    {showStudy && <StudyModal plans={data.plans} onClose={() => setShowStudy(false)} onSave={(s: Omit<Study, "id">) => { update({studies: [...data.studies, {...s, id: uid()}]}); setShowStudy(false); setNotice("勉強記録を保存しました"); }}/>} 
    {pendingDelete && <ConfirmModal onCancel={() => setPendingDelete(null)} onConfirm={confirmRemove} />}
  </div>;
}

function LoadingScreen() { return <div className="auth-screen"><div className="auth-card"><div className="brand-mark">S</div><h1>Study Manager</h1><p>学習スペースを準備しています…</p><div className="auth-loader"/></div></div>; }
function LoginScreen({onLogin, onLocalLogin}: {onLogin: (role: "student" | "parent") => void; onLocalLogin: (email: string, name: string, role: "student" | "parent", inviteCode?: string) => void}) { const [role, setRole] = useState<"student" | "parent">("student"); const [email, setEmail] = useState(""); const [name, setName] = useState(""); const [inviteCode, setInviteCode] = useState(""); return <div className="auth-screen"><div className="auth-card"><div className="brand-mark">S</div><span className="eyebrow">YOUR STUDY SPACE</span><h1>Study Manager</h1><p>{role === "student" ? <>計画を立てて、できたことを残して、<br/>次の一歩を自分で選べる場所。</> : <>お子さまの学習状況を見守り、<br/>無理なく応援するための保護者スペース。</>}</p><div className="role-switch" role="tablist" aria-label="利用者を選択"><button type="button" className={role === "student" ? "active" : ""} onClick={() => setRole("student")}>生徒として使う</button><button type="button" className={role === "parent" ? "active" : ""} onClick={() => setRole("parent")}>保護者として使う</button></div><div className="role-note"><Users size={15}/><span>{role === "student" ? "勉強の計画・記録・成績を管理します。" : "保護者専用の画面で共有された情報だけを確認します。"}</span></div><form className="local-login" onSubmit={e => { e.preventDefault(); if (email.trim()) onLocalLogin(email, name, role, inviteCode.trim().toUpperCase()); }}><label>メールアドレス<input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@example.com" required /></label><label>{role === "parent" ? "保護者名（任意）" : "表示名（任意）"}<input value={name} onChange={e => setName(e.target.value)} placeholder={role === "parent" ? "お母さん" : "たろう"} /></label>{role === "parent" && <label>生徒から受け取った招待コード（任意）<input value={inviteCode} onChange={e => setInviteCode(e.target.value)} placeholder="AB12-CD34" maxLength={9}/></label>}<button className="primary auth-login" type="submit">{role === "parent" ? "保護者スペースへログイン" : "生徒スペースへログイン"} <ChevronRight size={16}/></button></form><div className="login-divider"><span>または</span></div><button className="outline auth-login" onClick={() => { localStorage.setItem("study-manager-entry-role", role); if (role === "parent" && inviteCode.trim()) localStorage.setItem("study-manager-pending-invite", inviteCode.trim().toUpperCase()); window.location.href = "/api/auth/google"; }}><span className="google-mark">G</span> Googleでログイン <ChevronRight size={16}/></button><button className="text-login" onClick={() => onLogin(role)}>Manusアカウントでログイン</button><small><ShieldCheck size={13}/> {role === "parent" ? "保護者は生徒のパスワードを使わず、招待コードで安全に連携します。" : "GoogleログインはOAuth設定後に利用できます。未設定でもメールログインは使えます。"}</small><div className="auth-legal"><a href="/privacy.html" target="_blank" rel="noreferrer">プライバシーポリシー</a><span>・</span><a href="/terms.html" target="_blank" rel="noreferrer">利用規約</a></div></div></div>; }
function Section({title, eyebrow, subtitle, action, children}: any) { return <div className="page"><div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>{children}</div>; }
function Metric({label, value, delta, positive}: any) { return <div className="metric-card"><span>{label}</span><b>{value}</b><small className={positive ? "positive" : ""}>{delta}</small></div>; }
function Dashboard({data, displayName, todayPlans, openTasks, goalRate, average, chartData, onNavigate, onToggle, onQuickAdd, overdueTasks, upcomingExams, todayEvents, todayReviews, streakDays}: any) { return <div className="page dashboard"><div className="welcome-row"><div><span className="eyebrow">{formatDate(today)}</span><h1>今日の一歩を、<br/><em>ここから。</em></h1><p>{displayName}さん、今日は何から始めますか？</p></div><div className="quick-actions"><button className="primary" onClick={() => onQuickAdd("plan")}><Plus size={16}/> 計画</button><button className="outline" onClick={() => onQuickAdd("task")}><ListChecks size={16}/> 課題</button><button className="outline" onClick={() => onQuickAdd("study")}><Clock3 size={16}/> 記録</button></div></div><div className="metric-grid"><Metric label="今日の勉強時間" value={`${data.studies.filter((s: Study) => s.date === today).reduce((a: number,s: Study)=>a+s.minutes,0)}分`} delta="記録すると反映されます" positive/><Metric label="未完了の課題" value={`${openTasks.length}件`} delta="期限が近い順に表示"/><Metric label="最新の平均点" value={`${average}点`} delta="テストを登録すると比較できます"/><Metric label="今週の目標" value={`${goalRate}%`} delta={`${data.goal.hours}時間を目標`}/></div><div className="action-center"><div className="action-center-head"><div><span className="eyebrow">NEXT ACTIONS</span><h3>今日のアクションセンター</h3><p>期限と予定を見て、最初の一つを決めましょう。</p></div><div className="streak-badge"><strong>{streakDays}</strong><span>日連続<br/>学習中</span></div></div><div className="action-columns"><div className={`action-item ${overdueTasks.length ? "has-alert" : ""}`}><div className="action-icon">{overdueTasks.length ? "!" : "✓"}</div><div><b>{overdueTasks.length ? `期限切れの課題が${overdueTasks.length}件あります` : "期限切れの課題はありません"}</b><span>{overdueTasks.length ? `${overdueTasks[0].title} などを確認しましょう。` : "課題を追加すると、ここで優先順位を確認できます。"}</span></div><button className="link-btn" onClick={() => onNavigate("tasks")}>課題を見る <ChevronRight size={14}/></button></div><div className="action-item"><div className="action-icon exam">□</div><div><b>{upcomingExams.length ? `次のテスト：${upcomingExams[0].name}` : "次のテストを登録しましょう"}</b><span>{upcomingExams.length ? `${upcomingExams[0].date.replaceAll("-", "/")} 実施予定` : "テスト日から勉強計画を立てられます。"}</span></div><button className="link-btn" onClick={() => onNavigate("exams")}>成績を見る <ChevronRight size={14}/></button></div><div className="action-item"><div className="action-icon calendar">□</div><div><b>{todayEvents.length ? `今日の学校予定が${todayEvents.length}件あります` : "今日の学校予定はありません"}</b><span>{todayEvents.length ? todayEvents[0].title : "行事や小テストを登録できます。"}</span></div><button className="link-btn" onClick={() => onNavigate("school")}>予定を見る <ChevronRight size={14}/></button></div><div className="action-item"><div className="action-icon review">↻</div><div><b>{todayReviews.length ? `今日の復習が${todayReviews.length}件あります` : "今日の復習はありません"}</b><span>{todayReviews.length ? todayReviews[0].unit : "間違えた問題を登録すると表示されます。"}</span></div><button className="link-btn" onClick={() => onNavigate("weaknesses")}>復習する <ChevronRight size={14}/></button></div></div></div><div className="dash-grid"><div className="panel today-panel"><div className="panel-head"><div><b>今日やること</b><span>{formatDate(today)}</span></div><button className="link-btn" onClick={() => onNavigate("plans")}>すべて見る <ChevronRight size={15}/></button></div>{todayPlans.map((p: Plan) => <div className="today-item" key={p.id}><button className={`check ${p.done ? "checked" : ""}`} onClick={() => onToggle(p.id)}>{p.done && <Check size={14}/>}</button><div><b>{p.content}</b><span>{p.subject} ・ {p.minutes}分</span></div><time>{p.priority}</time></div>)}{todayPlans.length === 0 && <div className="empty-state"><CalendarDays size={24}/><b>今日の計画はありません</b><span>まずは一つ、やることを決めてみましょう。</span></div>}<button className="add-line" onClick={() => onNavigate("plans")}><Plus size={15}/> 計画を追加</button></div><div className="panel progress-panel"><div className="panel-head"><div><b>今週の進捗</b><span>今週の記録</span></div><TrendingUp size={18} className="panel-icon"/></div><div className="big-progress"><strong>{goalRate}<small>%</small></strong><div><div className="progress"><i style={{width: `${goalRate}%`}}/></div><span>{Math.floor(data.studies.reduce((a:number,s:Study)=>a+s.minutes,0)/60)}時間{data.studies.reduce((a:number,s:Study)=>a+s.minutes,0)%60}分 / {data.goal.hours}時間</span></div></div><div className="week-bars">{["月","火","水","木","金","土","日"].map((d,i)=><div key={d}><i style={{height: `${[45,75,55,88,40,62,0][i]}%`}}/><span>{d}</span></div>)}</div></div><div className="panel chart-panel"><div className="panel-head"><div><b>最近の成績</b><span>教科別の推移</span></div><button className="link-btn" onClick={() => onNavigate("exams")}>詳しく見る <ChevronRight size={15}/></button></div><div className="mini-chart"><ResponsiveContainer width="100%" height={210}><LineChart data={chartData}><CartesianGrid vertical={false} stroke="#edf0f4"/><XAxis dataKey="subject" tickLine={false} axisLine={false}/><YAxis domain={[0,100]} hide/><Tooltip/><Line type="monotone" dataKey="latest" stroke="#183b67" strokeWidth={3} dot={{r:3}}/><Line type="monotone" dataKey="previous" stroke="#b4bfce" strokeWidth={2} strokeDasharray="4 4"/></LineChart></ResponsiveContainer></div></div><div className="panel insight-panel"><div className="insight-top"><div className="spark"><FileText size={17}/></div><span className="eyebrow">今日のメモ</span></div><h3>{data.weaknesses.find((w: Weakness) => !w.done)?.unit || "復習メモを追加しましょう"}</h3><p>{data.weaknesses.some((w: Weakness) => !w.done) ? "苦手・復習に登録した内容がここに表示されます。" : "テストや課題を登録すると、ここに次の一歩が表示されます。"}</p><button className="outline" onClick={() => onNavigate("weaknesses")}>復習リストを見る <ChevronRight size={15}/></button></div></div></div>; }

function Modal({title, children, onClose, onSubmit}: any) { return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><span className="eyebrow">NEW ENTRY</span><h2>{title}</h2></div><button className="icon-btn" onClick={onClose}><X size={18}/></button></div><form onSubmit={e => { e.preventDefault(); onSubmit(new FormData(e.currentTarget)); }}>{children}<div className="modal-actions"><button type="button" className="outline" onClick={onClose}>キャンセル</button><button className="primary" type="submit"><Check size={16}/> 保存する</button></div></form></div></div>; }
function ConfirmModal({onCancel, onConfirm}: {onCancel: () => void; onConfirm: () => void}) { return <div className="modal-backdrop"><div className="modal confirm-modal"><div className="modal-head"><div><span className="eyebrow">CONFIRM</span><h2>この項目を削除しますか？</h2></div><button className="icon-btn" type="button" onClick={onCancel}><X size={18}/></button></div><p className="confirm-copy">削除したデータは一覧から消えます。元に戻すにはバックアップから復元してください。</p><div className="modal-actions"><button type="button" className="outline" onClick={onCancel}>キャンセル</button><button className="danger-button" type="button" onClick={onConfirm}>削除する</button></div></div></div>; }
function Field({label, name, type="text", defaultValue, required=true}: any) { return <label className="field">{label}<input name={name} type={type} defaultValue={defaultValue} required={required}/></label>; }
function TaskModal({onClose,onSave,initial}: any) { return <Modal title={initial ? "課題を編集" : "課題を追加"} onClose={onClose} onSubmit={(f:FormData)=>onSave({title:String(f.get("title")),subject:String(f.get("subject")),due:String(f.get("due")),minutes:Number(f.get("minutes")),kind:String(f.get("kind"))})}><Field label="課題名" name="title" defaultValue={initial?.title || ""}/><div className="form-grid"><Field label="教科" name="subject" defaultValue={initial?.subject || "数学"}/><Field label="種別" name="kind" defaultValue={initial?.kind || "学校"}/><Field label="提出日" name="due" type="date" defaultValue={initial?.due || today}/><Field label="所要時間（分）" name="minutes" type="number" defaultValue={initial?.minutes || 30}/></div></Modal>; }
function PlanModal({onClose,onSave,initial}: any) { return <Modal title={initial ? "計画を編集" : "計画を追加"} onClose={onClose} onSubmit={(f:FormData)=>onSave({date:String(f.get("date")),subject:String(f.get("subject")),content:String(f.get("content")),minutes:Number(f.get("minutes")),priority:String(f.get("priority"))})}><Field label="勉強内容" name="content" defaultValue={initial?.content || ""}/><div className="form-grid"><Field label="日付" name="date" type="date" defaultValue={initial?.date || today}/><Field label="教科" name="subject" defaultValue={initial?.subject || "数学"}/><Field label="予定時間（分）" name="minutes" type="number" defaultValue={initial?.minutes || 30}/><Field label="優先度" name="priority" defaultValue={initial?.priority || "中"}/></div></Modal>; }
function ExamModal({onClose,onSave}: any) { return <Modal title="テストを追加" onClose={onClose} onSubmit={(f:FormData)=>{const scores:Record<string,number>={}; mainSubjects.forEach(s=>scores[s]=Number(f.get(s))); onSave({id:uid(),name:String(f.get("name")),date:String(f.get("date")),term:String(f.get("term")),max:Number(f.get("max")),scores});}}><div className="form-grid"><Field label="テスト名" name="name" defaultValue="2学期期末テスト"/><Field label="実施日" name="date" type="date" defaultValue={today}/><Field label="学期" name="term" defaultValue="2学期"/><Field label="満点" name="max" type="number" defaultValue="100"/></div><div className="score-grid">{mainSubjects.map(s=><Field key={s} label={`${s}の点数`} name={s} type="number" defaultValue="0"/> )}</div></Modal>; }
function ReviewModal({weakness, onClose, onComplete}: {weakness: Weakness; onClose: () => void; onComplete: (result: {correct: boolean; understanding: number; seconds?: number; memo?: string}) => void}) { const [revealed, setRevealed] = useState(false); const [correct, setCorrect] = useState(true); const [understanding, setUnderstanding] = useState(3); return <div className="modal-backdrop"><div className="modal review-modal"><div className="modal-head"><div><span className="eyebrow">REVIEW SESSION</span><h2>{weakness.unit}</h2><p className="review-meta">{weakness.subject} ・ {weakness.cause} ・ 今日の復習</p></div><button className="icon-btn" onClick={onClose}><X size={18}/></button></div><div className="review-question"><b>問題</b><p>{weakness.question || "問題文は登録されていません。ノートの内容を思い出して解き直しましょう。"}</p>{weakness.imageData && <img src={weakness.imageData} alt="問題・答案"/>}</div><button type="button" className="outline reveal-button" onClick={() => setRevealed(value => !value)}>{revealed ? "解答・解説を隠す" : "解答・解説を表示"}</button>{revealed && <div className="review-answer"><b>正解</b><p>{weakness.answer || "正解は未登録です。"}</p><b>解説</b><p>{weakness.explanation || "解説は未登録です。"}</p></div>}<form onSubmit={e => { e.preventDefault(); const form = new FormData(e.currentTarget); onComplete({ correct, understanding, seconds: Number(form.get("seconds")) || undefined, memo: String(form.get("memo") || "") }); }}><div className="review-result-grid"><label className="field">結果<select value={correct ? "correct" : "wrong"} onChange={e => setCorrect(e.target.value === "correct")}><option value="correct">正解</option><option value="wrong">不正解</option></select></label><label className="field">理解度<select value={understanding} onChange={e => setUnderstanding(Number(e.target.value))}>{[1,2,3,4,5].map(value => <option key={value} value={value}>{value} / 5</option>)}</select></label><Field label="回答時間（秒・任意）" name="seconds" type="number" required={false}/></div><Field label="振り返りメモ（任意）" name="memo" required={false}/><div className="modal-actions"><button type="button" className="outline" onClick={onClose}>あとで復習</button><button className="primary" type="submit"><Check size={16}/> 結果を保存</button></div></form></div></div>; }
function WeakModal({onClose,onSave,initial}: {onClose: () => void; onSave: (weakness: Omit<Weakness, "id" | "done">) => void; initial?: Weakness | null}) { const submit = (f: FormData) => { const base = {subject:String(f.get("subject")),unit:String(f.get("unit")),cause:String(f.get("cause")),review:String(f.get("review")),question:String(f.get("question")),answer:String(f.get("answer")),explanation:String(f.get("explanation")),imageData:initial?.imageData || "",difficulty:String(f.get("difficulty")),memo:String(f.get("memo")),history:initial?.history || []}; const file = f.get("imageFile"); if (file instanceof File && file.size > 0) { if (file.size > 100_000) { window.alert("画像は100KB以下にしてください"); return; } const reader = new FileReader(); reader.onload = () => onSave({...base, imageData: String(reader.result)}); reader.readAsDataURL(file); } else onSave(base); }; return <Modal title={initial ? "間違いノートを編集" : "間違いノートを追加"} onClose={onClose} onSubmit={submit}><Field label="問題名・単元" name="unit" defaultValue={initial?.unit || ""}/><div className="form-grid"><Field label="教科" name="subject" defaultValue={initial?.subject || "数学"}/><label className="field">間違いの原因<select name="cause" defaultValue={initial?.cause || "知識不足"}><option>知識不足</option><option>計算ミス</option><option>読み違い</option><option>解き方が分からない</option><option>時間不足</option><option>その他</option></select></label><label className="field">難易度<select name="difficulty" defaultValue={initial?.difficulty || "標準"}><option>やさしい</option><option>標準</option><option>難しい</option></select></label><Field label="次回の復習日" name="review" type="date" defaultValue={initial?.review || new Date(Date.now() + 86400000).toISOString().slice(0,10)}/></div><label className="field">問題文（任意）<textarea name="question" defaultValue={initial?.question || ""} placeholder="問題文や、どこで間違えたか"/></label><div className="form-grid"><Field label="正解（任意）" name="answer" defaultValue={initial?.answer || ""} required={false}/><Field label="解説（任意）" name="explanation" defaultValue={initial?.explanation || ""} required={false}/><label className="field">問題・答案画像（任意）<input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"/></label><Field label="メモ（任意）" name="memo" defaultValue={initial?.memo || ""} required={false}/></div></Modal>; }
function StudyModal({onClose,onSave,plans}: {onClose: () => void; onSave: (study: Omit<Study, "id">) => void; plans: Plan[]}) { return <Modal title="勉強時間を記録" onClose={onClose} onSubmit={(f:FormData)=>onSave({date:String(f.get("date")),subject:String(f.get("subject")),minutes:Number(f.get("minutes")),note:String(f.get("note")),planId:String(f.get("planId") || "") || undefined,method:String(f.get("method")),understanding:Number(f.get("understanding")) || undefined,difficultPoint:String(f.get("difficultPoint")),nextAction:String(f.get("nextAction"))})}><div className="form-grid"><Field label="日付" name="date" type="date" defaultValue={today}/><Field label="教科" name="subject" defaultValue="数学"/><Field label="勉強時間（分）" name="minutes" type="number" defaultValue="25"/><label className="field">対応する計画（任意）<select name="planId" defaultValue=""><option value="">紐付けなし</option>{plans.filter(plan => plan.status !== "cancelled").map(plan => <option key={plan.id} value={plan.id}>{plan.date}・{plan.content}</option>)}</select></label><label className="field">学習方法<select name="method" defaultValue="問題演習"><option>問題演習</option><option>教科書を読む</option><option>ノートをまとめる</option><option>暗記</option><option>間違い直し</option><option>一問一答</option><option>その他</option></select></label><label className="field">理解度<select name="understanding" defaultValue=""><option value="">記録しない</option>{[1,2,3,4,5].map(value => <option key={value} value={value}>{value} / 5</option>)}</select></label></div><Field label="メモ（任意）" name="note" required={false}/><div className="form-grid"><Field label="難しかった点（任意）" name="difficultPoint" required={false}/><Field label="次回取り組むこと（任意）" name="nextAction" required={false}/></div></Modal>; }
function AnalyticsDashboard({data, period, start, end, onPeriodChange, onStartChange, onEndChange, onNavigate, onAutoAdjust, onUndoAdjustment}: {data: Store; period: "week" | "7days" | "month" | "30days" | "custom"; start: string; end: string; onPeriodChange: (period: "week" | "7days" | "month" | "30days" | "custom") => void; onStartChange: (date: string) => void; onEndChange: (date: string) => void; onNavigate: (page: string) => void; onAutoAdjust: () => void; onUndoAdjustment: () => void}) {
  const range = period === "week" ? {label: "今週", start: startOfWeek(today), end: today} : period === "7days" ? {label: "過去7日間", start: addDays(today, -6), end: today} : period === "month" ? {label: "今月", start: `${today.slice(0, 7)}-01`, end: today} : period === "30days" ? {label: "過去30日間", start: addDays(today, -29), end: today} : {label: "指定期間", start, end};
  const inRange = (date: string) => date >= range.start && date <= range.end;
  const plans = data.plans.filter(plan => inRange(plan.date));
  const studies = data.studies.filter(study => inRange(study.date));
  const plannedMinutes = plans.reduce((sum, plan) => sum + Math.max(0, plan.minutes), 0);
  const completedPlanMinutes = plans.filter(plan => plan.done).reduce((sum, plan) => sum + Math.max(0, plan.minutes), 0);
  const actualMinutes = studies.reduce((sum, study) => sum + Math.max(0, study.minutes), 0);
  const overdueTasks = data.tasks.filter(task => !task.done && task.due < today);
  const dueReviews = data.reviewSchedules.filter(schedule => schedule.status === "pending" && schedule.due <= today);
  const latest = [...data.exams].sort((a, b) => b.date.localeCompare(a.date))[0];
  const latestTotal = latest ? Object.values(latest.scores).reduce((sum, score) => sum + score, 0) : null;
  const subjectMinutes = subjects.map(subject => ({subject, minutes: studies.filter(study => study.subject === subject).reduce((sum, study) => sum + study.minutes, 0)})).filter(item => item.minutes > 0);
  const methodMinutes = ["問題演習", "教科書を読む", "ノートをまとめる", "暗記", "間違い直し", "一問一答", "その他"].map(method => ({method, minutes: studies.filter(study => study.method === method).reduce((sum, study) => sum + study.minutes, 0)})).filter(item => item.minutes > 0);
  const targetRows = mainSubjects.map(subject => { const target = data.goal.subjectTargets?.[subject]; const latestScore = latest?.scores[subject]; return {subject, target, latestScore, gap: target !== undefined && latestScore !== undefined ? target - latestScore : null}; }).filter(item => item.target !== undefined || item.latestScore !== undefined);
  const causeCounts = ["知識不足", "計算ミス", "読み違い", "解き方が分からない", "時間不足", "その他"].map(cause => ({cause, count: data.weaknesses.filter(weakness => weakness.cause === cause).length})).filter(item => item.count > 0);
  const trend = [...data.exams].filter(exam => exam.date <= range.end).sort((a, b) => a.date.localeCompare(b.date)).slice(-6).map(exam => ({name: exam.name.length > 8 ? `${exam.name.slice(0, 8)}…` : exam.name, date: exam.date.slice(5), score: Math.round((Object.values(exam.scores).reduce((sum, score) => sum + score, 0) / Math.max(1, Object.keys(exam.scores).length * exam.max)) * 100)}));
  const hasLinkedStudyData = studies.some(study => Boolean((study as Study & {planId?: string}).planId));
  const weeklyRate = hasLinkedStudyData && plannedMinutes > 0 ? Math.round((completedPlanMinutes / plannedMinutes) * 100) : null;
  const suggestions = [
    dueReviews.length ? {title: "期限を過ぎた復習から始める", reason: `${dueReviews.length}件の復習予定が今日以前です。`, action: () => onNavigate("weaknesses")} : null,
    overdueTasks.length ? {title: "期限超過の課題を整理する", reason: `${overdueTasks.length}件の未完了課題があります。`, action: () => onNavigate("tasks")} : null,
    latestTotal !== null && latestTotal < data.goal.score ? {title: "目標点との差が大きい教科を確認する", reason: `最新合計は${latestTotal}点、全体目標は${data.goal.score}点です。`, action: () => onNavigate("exams")} : null,
    !studies.length ? {title: "勉強記録を1件残す", reason: `${range.label}の実績時間がまだありません。`, action: () => onNavigate("timer")} : null,
  ].filter(Boolean) as {title: string; reason: string; action: () => void}[];
  return <Section title="学習分析" eyebrow="LEARNING ANALYTICS" subtitle="計画・実績・成績・復習を同じ期間で確認し、次の行動につなげます。"><div className="analysis-period"><b>集計期間</b>{([ ["week", "今週"], ["7days", "過去7日間"], ["month", "今月"], ["30days", "過去30日間"], ["custom", "期間指定"]] as const).map(([value, label]) => <button key={value} className={period === value ? "active" : ""} onClick={() => onPeriodChange(value)}>{label}</button>)}<span>{range.start.replaceAll("-", "/")} 〜 {range.end.replaceAll("-", "/")}</span>{period === "custom" && <><input type="date" value={start} onChange={e => onStartChange(e.target.value)}/><input type="date" value={end} onChange={e => onEndChange(e.target.value)}/></>}</div><div className="metric-grid"><Metric label={`${range.label}の計画時間`} value={plannedMinutes ? `${Math.floor(plannedMinutes / 60)}時間${plannedMinutes % 60}分` : "記録なし"} delta={`${plans.length}件の計画`} /><Metric label={`${range.label}の実績時間`} value={actualMinutes ? `${Math.floor(actualMinutes / 60)}時間${actualMinutes % 60}分` : "記録なし"} delta={`${studies.length}件の勉強記録`} positive/><Metric label="計画達成率" value={weeklyRate === null ? "データ不足" : `${weeklyRate}%`} delta={weeklyRate === null ? "計画時間がないため未計算" : `完了計画 ${completedPlanMinutes}分 ÷ 計画 ${plannedMinutes}分`} /><Metric label="復習待ち" value={`${dueReviews.length}件`} delta="今日以前の未完了予定" /></div><div className="analysis-grid"><div className="chart-card"><div className="card-title"><div><b>教科別の実績時間</b><span>{range.label}・記録がある教科のみ</span></div></div>{subjectMinutes.length ? <div className="chart-box"><ResponsiveContainer width="100%" height={250}><BarChart data={subjectMinutes}><CartesianGrid vertical={false} stroke="#e6ebf1"/><XAxis dataKey="subject" tickLine={false} axisLine={false}/><YAxis tickLine={false} axisLine={false}/><Tooltip/><Bar dataKey="minutes" name="分" fill="#183b67" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div> : <div className="analysis-empty">この期間の勉強記録はありません。</div>}</div><div className="chart-card"><div className="card-title"><div><b>テスト得点率の推移</b><span>満点が違っても得点率で比較</span></div></div>{trend.length > 1 ? <div className="chart-box"><ResponsiveContainer width="100%" height={250}><LineChart data={trend}><CartesianGrid vertical={false} stroke="#e6ebf1"/><XAxis dataKey="date" tickLine={false} axisLine={false}/><YAxis domain={[0,100]} tickLine={false} axisLine={false}/><Tooltip/><Line type="monotone" dataKey="score" name="得点率" stroke="#c28b35" strokeWidth={3} dot={{r:3}}/></LineChart></ResponsiveContainer></div> : <div className="analysis-empty">比較できるテスト結果が2件未満です。</div>}</div></div><div className="analysis-grid"><div className="analysis-card"><div className="card-title"><div><b>復習・原因の状況</b><span>登録データをそのまま集計</span></div></div><div className="analysis-lines"><p><span>登録問題</span><b>{data.weaknesses.length}件</b></p><p><span>復習待ち</span><b>{dueReviews.length}件</b></p>{causeCounts.length ? causeCounts.map(item => <p key={item.cause}><span>{item.cause}</span><b>{item.count}件</b></p>) : <small>原因データはまだありません。</small>}</div></div><div className="analysis-card"><div className="card-title"><div><b>計画の状態</b><span>同じ予定時間の重複は計上していません</span></div></div><div className="analysis-lines"><p><span>未完了タスク</span><b>{data.tasks.filter(task => !task.done).length}件</b></p><p><span>期限超過タスク</span><b>{overdueTasks.length}件</b></p><p><span>完了した計画</span><b>{plans.filter(plan => plan.done).length}件</b></p><p><span>実績とのID紐付け</span><b className="muted-value">未設定</b></p></div><small className="analysis-note">現在の計画と勉強記録には対応IDがないため、厳密な実績ベースの達成率は「計画達成率」で推測していません。</small></div></div><div className="analysis-grid"><div className="analysis-card"><div className="card-title"><div><b>教科別目標の進捗</b><span>未設定の目標は推測しません</span></div></div><div className="analysis-lines">{targetRows.length ? targetRows.map(item => <p key={item.subject}><span>{item.subject}</span><b>{item.latestScore === undefined ? "得点なし" : `${item.latestScore}点`} / {item.target === undefined ? "目標未設定" : `${item.target}点`} {item.gap === null ? "" : item.gap > 0 ? `（あと${item.gap}点）` : "（目標達成）"}</b></p>) : <small>教科別目標またはテスト結果がありません。</small>}</div></div><div className="analysis-card"><div className="card-title"><div><b>学習方法別の実績</b><span>時間と成績の因果関係は断定しません</span></div></div><div className="analysis-lines">{methodMinutes.length ? methodMinutes.map(item => <p key={item.method}><span>{item.method}</span><b>{item.minutes}分</b></p>) : <small>学習方法を記録すると表示します。</small>}</div></div></div><div className="adjustment-panel"><div><b>計画の自動調整</b><span>期限超過の未完了計画だけを候補にします。固定・完了・キャンセル済みは変更しません。</span></div><div className="adjustment-actions"><button className="outline" onClick={onAutoAdjust}>調整案を確認</button><button className="outline" onClick={onUndoAdjustment}>直前の変更を取り消す</button></div></div><div className="suggestion-panel"><div className="card-title"><div><b>次に取り組む候補</b><span>保存済みデータから計算した提案です。自動適用はしません。</span></div><TrendingUp size={18} className="panel-icon"/></div>{suggestions.length ? suggestions.map((suggestion, index) => <div className="suggestion-row" key={suggestion.title}><span className="suggestion-index">{index + 1}</span><div><b>{suggestion.title}</b><span>{suggestion.reason}</span></div><button className="link-btn" onClick={suggestion.action}>確認する <ChevronRight size={14}/></button></div>) : <div className="analysis-empty">今すぐ優先すべき項目はありません。記録が増えると提案が具体的になります。</div>}</div></Section>;
}
const addDays = (iso: string, amount: number) => { const date = new Date(`${iso}T00:00:00`); date.setDate(date.getDate() + amount); return date.toISOString().slice(0, 10); };
const startOfWeek = (iso: string) => { const date = new Date(`${iso}T00:00:00`); const day = date.getDay(); date.setDate(date.getDate() - (day === 0 ? 6 : day - 1)); return date.toISOString().slice(0, 10); };

function SchoolCalendar({data, view, onViewChange, onAddEvent, onAddTimetable, onDeleteEvent, onDeleteTimetable}: {data: Store; view: "list" | "timetable"; onViewChange: (view: "list" | "timetable") => void; onAddEvent: () => void; onAddTimetable: () => void; onDeleteEvent: (id: string) => void; onDeleteTimetable: (id: string) => void}) { const days = ["月", "火", "水", "木", "金"]; const events = [...data.events].sort((a, b) => a.date.localeCompare(b.date)); return <Section title="学校生活" eyebrow="SCHOOL LIFE" subtitle="学校行事、テスト、小テスト、提出期限と時間割を一つにまとめます。" action={<div className="section-actions"><button className="outline" onClick={onAddTimetable}><Plus size={16}/> 時間割を登録</button><button className="primary" onClick={onAddEvent}><Plus size={16}/> 学校予定を追加</button></div>}><div className="view-switch"><button className={view === "list" ? "active" : ""} onClick={() => onViewChange("list")}>予定一覧</button><button className={view === "timetable" ? "active" : ""} onClick={() => onViewChange("timetable")}>週間時間割</button></div>{view === "list" ? <div className="list-card school-events">{events.length ? events.map(event => <div className="list-row" key={event.id}><div className="event-date"><b>{event.date.slice(5).replace("-", "/")}</b><small>{formatDate(event.date).split(" ").at(-1)}</small></div><div className="row-main"><b>{event.title}</b><span><label className="tag">{event.kind}</label> {event.subject || "教科なし"}{event.note ? ` ・ ${event.note}` : ""}</span></div><button className="text-danger" onClick={() => onDeleteEvent(event.id)}>削除</button></div>) : <div className="empty-state"><CalendarDays size={24}/><b>学校予定はまだありません</b><span>定期テスト、行事、小テスト、提出期限を登録できます。</span><button className="outline" onClick={onAddEvent}>最初の予定を追加</button></div>}</div> : <div className="timetable-grid"><div className="timetable-corner">時限</div>{days.map(day => <div className="timetable-day" key={day}>{day}</div>)}{[1,2,3,4,5,6].map(period => <React.Fragment key={period}><div className="timetable-period">{period}限</div>{days.map((_, day) => { const entry = data.timetable.find(item => item.day === day && item.period === period); return <div className={`timetable-cell ${entry ? "filled" : ""}`} key={`${day}-${period}`}>{entry ? <><b>{entry.subject}</b><small>{entry.room || "教室未設定"}</small><button className="cell-delete" onClick={() => onDeleteTimetable(entry.id)}>×</button></> : <span>—</span>}</div>; })}</React.Fragment>)}</div>}</Section>; }
function EventModal({onClose, onSave}: {onClose: () => void; onSave: (event: Omit<SchoolEvent, "id">) => void}) { return <Modal title="学校予定を追加" onClose={onClose} onSubmit={(f: FormData) => onSave({title: String(f.get("title")), date: String(f.get("date")), kind: String(f.get("kind")), subject: String(f.get("subject")), note: String(f.get("note"))})}><Field label="予定名" name="title"/><div className="form-grid"><Field label="日付" name="date" type="date" defaultValue={today}/><label className="field">種別<select name="kind" defaultValue="学校行事"><option>学校行事</option><option>小テスト</option><option>定期テスト</option><option>提出期限</option><option>部活動</option></select></label><Field label="教科（任意）" name="subject" required={false}/><Field label="メモ（任意）" name="note" required={false}/></div></Modal>; }
function TimetableModal({onClose, onSave}: {onClose: () => void; onSave: (entry: Omit<TimetableEntry, "id">) => void}) { return <Modal title="時間割を登録" onClose={onClose} onSubmit={(f: FormData) => onSave({day: Number(f.get("day")), period: Number(f.get("period")), subject: String(f.get("subject")), room: String(f.get("room")), teacher: String(f.get("teacher"))})}><div className="form-grid"><label className="field">曜日<select name="day" defaultValue="0">{["月", "火", "水", "木", "金"].map((day, i) => <option key={day} value={i}>{day}曜日</option>)}</select></label><label className="field">時限<select name="period" defaultValue="1">{[1,2,3,4,5,6,7,8].map(period => <option key={period} value={period}>{period}限</option>)}</select></label><Field label="教科" name="subject"/><Field label="教室（任意）" name="room" required={false}/><Field label="先生（任意）" name="teacher" required={false}/></div></Modal>; }




